import { Inject, Injectable, Optional } from '@nestjs/common';
import { DatabaseService } from '../database/database.service.js';
import { uuidV7 } from '@handstack/domain';
import {
  WorkflowRuntime,
  RepositoryWorkflowStore,
  type WorkflowStore,
  type Workflow,
  type WorkflowEdge,
  type WorkflowExecution,
  type WorkflowNode,
  type WorkflowStepExecution,
  type WorkflowTrigger,
} from '@handstack/workflows';
import { ValidationError } from '@handstack/shared';

export interface WorkflowDefinitionInput {
  readonly organizationId: string;
  readonly name: string;
  readonly trigger: WorkflowTrigger;
  readonly nodes: readonly WorkflowNode[];
  readonly edges: readonly WorkflowEdge[];
}

@Injectable()
export class WorkflowRuntimeService {
  private readonly workflows = new Map<string, Workflow>();
  private readonly store: WorkflowStore | undefined;
  private readonly runtime: WorkflowRuntime;

  constructor(@Optional() @Inject(DatabaseService) database?: DatabaseService) {
    this.store =
      database === undefined
        ? undefined
        : new RepositoryWorkflowStore((name) => database.adapter.repository(name));
    this.runtime = new WorkflowRuntime((node, input) => {
      // Core nodes are intentionally side-effect free here. Providers can replace this executor.
      if (node.kind === 'Condition' && typeof node.config.pass === 'boolean' && !node.config.pass)
        return Promise.resolve({ input, skipped: true });
      return Promise.resolve(input);
    }, this.store);
  }

  async list(organizationId: string): Promise<readonly Workflow[]> {
    const durable = (await this.store?.listWorkflows(organizationId)) ?? [];
    for (const workflow of durable) {
      this.workflows.set(this.key(organizationId, workflow.id), workflow);
      this.runtime.register(workflow);
    }
    return [...this.workflows.values()].filter(
      (workflow) => workflow.organizationId === organizationId,
    );
  }

  async get(organizationId: string, workflowId: string): Promise<Workflow> {
    const workflow = this.workflows.get(this.key(organizationId, workflowId));
    if (workflow?.organizationId === organizationId) return workflow;
    const durable = await this.store?.findWorkflow(organizationId, workflowId);
    if (durable === undefined) throw new ValidationError('Workflow not found');
    this.workflows.set(this.key(organizationId, workflowId), durable);
    this.runtime.register(durable);
    return durable;
  }

  async create(input: WorkflowDefinitionInput): Promise<Workflow> {
    const now = new Date();
    const workflow: Workflow = {
      id: uuidV7(),
      tenantId: input.organizationId,
      organizationId: input.organizationId,
      name: input.name,
      trigger: input.trigger,
      nodes: input.nodes,
      edges: input.edges,
      published: false,
      version: 1,
      createdAt: now,
      updatedAt: now,
    };
    this.runtime.register(workflow);
    this.workflows.set(this.key(input.organizationId, workflow.id), workflow);
    await this.store?.saveWorkflow(workflow);
    return workflow;
  }

  async publish(organizationId: string, workflowId: string): Promise<Workflow> {
    const current = await this.get(organizationId, workflowId);
    const published: Workflow = { ...current, published: true, updatedAt: new Date() };
    this.runtime.register(published);
    this.workflows.set(this.key(organizationId, workflowId), published);
    await this.store?.saveWorkflow(published);
    return published;
  }

  start(input: {
    readonly organizationId: string;
    readonly workflowId: string;
    readonly principalId: string;
    readonly trigger: WorkflowTrigger;
    readonly payload: unknown;
    readonly signal?: AbortSignal;
  }): Promise<WorkflowExecution> {
    return this.get(input.organizationId, input.workflowId).then(async () => {
      const execution = await this.runtime.start(input);
      return execution;
    });
  }

  async getExecution(organizationId: string, executionId: string): Promise<WorkflowExecution> {
    const execution = this.runtime.get(organizationId, executionId);
    if (execution !== undefined) return execution;
    const durable = await this.store?.findExecution(organizationId, executionId);
    if (durable === undefined) throw new ValidationError('Workflow execution not found');
    const workflow = await this.get(organizationId, durable.workflowId);
    await this.runtime.hydrate(durable, workflow);
    return durable;
  }

  async listSteps(
    organizationId: string,
    executionId: string,
  ): Promise<readonly WorkflowStepExecution[]> {
    const execution = await this.getExecution(organizationId, executionId);
    const steps = await this.store?.listSteps(organizationId, execution.id);
    return steps ?? this.runtime.listSteps(organizationId, execution.id);
  }

  async approve(input: {
    readonly organizationId: string;
    readonly executionId: string;
    readonly approverId: string;
  }): Promise<WorkflowExecution> {
    const execution = await this.getExecution(input.organizationId, input.executionId);
    if (execution.status !== 'WAITING_APPROVAL' || execution.approvalId === undefined)
      throw new ValidationError('Workflow execution is not waiting for approval');
    await this.runtime.approve(input.organizationId, execution.approvalId, input.approverId);
    const resumed = await this.runtime.resume(
      input.organizationId,
      input.executionId,
      execution.approvalId,
    );
    return resumed;
  }

  async recover(input: {
    readonly organizationId: string;
    readonly executionId: string;
  }): Promise<WorkflowExecution> {
    const execution = await this.getExecution(input.organizationId, input.executionId);
    if (execution.status !== 'RUNNING')
      throw new ValidationError('Workflow execution is not recoverable');
    return this.runtime.recover(input.organizationId, input.executionId);
  }

  private key(organizationId: string, id: string): string {
    return `${organizationId}:${id}`;
  }
}
import { AuthorizationError, ValidationError } from '@handstack/shared';
import { Body, Controller, Get, Inject, Param, Post, Req, UseGuards } from '@nestjs/common';
import { ApiBearerAuth, ApiOperation, ApiTags } from '@nestjs/swagger';
import { z } from 'zod';
import { AccessTokenGuard } from '../auth/access-token.guard.js';
import { AuthRuntimeService } from '../auth/auth-runtime.service.js';
import {
  requireAuthentication,
  type AuthenticatedRequest,
} from '../auth/authentication-context.js';
import { IdentityAdministrationService } from '@handstack/identity-service';
import { WorkflowRuntimeService } from './workflow-runtime.service.js';

const nodeSchema = z.object({
  id: z.string().trim().min(1).max(128),
  kind: z.enum(['Agent', 'Capability', 'LLM', 'Tool', 'MCP', 'Condition', 'Human Approval']),
  config: z.record(z.string(), z.unknown()).default({}),
});
const edgeSchema = z.object({
  from: z.string().trim().min(1).max(128),
  to: z.string().trim().min(1).max(128),
  condition: z.string().max(2_000).optional(),
});
const createSchema = z.object({
  name: z.string().trim().min(1).max(200),
  trigger: z.enum(['manual', 'api', 'webhook', 'schedule', 'event']),
  nodes: z.array(nodeSchema).min(1).max(100),
  edges: z.array(edgeSchema).max(200),
});
const startSchema = z.object({
  trigger: z.enum(['manual', 'api', 'webhook', 'schedule', 'event']),
  payload: z.unknown(),
});
const approveSchema = z.object({ approverId: z.string().trim().min(1).max(200) });

@ApiTags('Workflows')
@ApiBearerAuth()
@Controller('api/v1/organizations/:organizationId/workflows')
@UseGuards(AccessTokenGuard)
export class WorkflowController {
  private readonly administration: IdentityAdministrationService;

  constructor(
    @Inject(WorkflowRuntimeService) private readonly runtime: WorkflowRuntimeService,
    @Inject(AuthRuntimeService) auth: AuthRuntimeService,
  ) {
    this.administration = new IdentityAdministrationService(auth.storage);
  }

  @Get()
  @ApiOperation({ summary: 'List workflows for an organization' })
  async list(
    @Param('organizationId') organizationId: string,
    @Req() request: AuthenticatedRequest,
  ) {
    await this.authorize(organizationId, request, 'workflows.read');
    return { items: await this.runtime.list(organizationId) };
  }

  @Post()
  @ApiOperation({ summary: 'Create a workflow draft' })
  async create(
    @Param('organizationId') organizationId: string,
    @Req() request: AuthenticatedRequest,
    @Body() value: unknown,
  ) {
    await this.authorize(organizationId, request, 'workflows.manage');
    const parsed = createSchema.safeParse(value);
    if (!parsed.success)
      throw new ValidationError(parsed.error.issues[0]?.message ?? 'Invalid workflow');
    return this.runtime.create({
      organizationId,
      name: parsed.data.name,
      trigger: parsed.data.trigger,
      nodes: parsed.data.nodes,
      edges: parsed.data.edges.map((edge) =>
        edge.condition === undefined
          ? { from: edge.from, to: edge.to }
          : { from: edge.from, to: edge.to, condition: edge.condition },
      ),
    });
  }

  @Post(':workflowId/publish')
  @ApiOperation({ summary: 'Publish a workflow' })
  async publish(
    @Param('organizationId') organizationId: string,
    @Param('workflowId') workflowId: string,
    @Req() request: AuthenticatedRequest,
  ) {
    await this.authorize(organizationId, request, 'workflows.manage');
    return this.runtime.publish(organizationId, workflowId);
  }

  @Post(':workflowId/executions')
  @ApiOperation({ summary: 'Start a workflow execution' })
  async start(
    @Param('organizationId') organizationId: string,
    @Param('workflowId') workflowId: string,
    @Req() request: AuthenticatedRequest,
    @Body() value: unknown,
  ) {
    const authentication = await this.authorize(organizationId, request, 'workflows.run');
    const parsed = startSchema.safeParse(value);
    if (!parsed.success)
      throw new ValidationError(parsed.error.issues[0]?.message ?? 'Invalid execution');
    return this.runtime.start({
      organizationId,
      workflowId,
      principalId: authentication.subject,
      ...parsed.data,
    });
  }

  @Get(':workflowId/executions/:executionId')
  @ApiOperation({ summary: 'Get workflow execution' })
  async getExecution(
    @Param('organizationId') organizationId: string,
    @Param('workflowId') workflowId: string,
    @Param('executionId') executionId: string,
    @Req() request: AuthenticatedRequest,
  ) {
    await this.authorize(organizationId, request, 'workflows.read');
    const execution = await this.runtime.getExecution(organizationId, executionId);
    if (execution.workflowId !== workflowId)
      throw new ValidationError('Workflow execution not found');
    return execution;
  }

  @Get(':workflowId/executions/:executionId/steps')
  @ApiOperation({ summary: 'List workflow step execution history' })
  async listSteps(
    @Param('organizationId') organizationId: string,
    @Param('workflowId') workflowId: string,
    @Param('executionId') executionId: string,
    @Req() request: AuthenticatedRequest,
  ) {
    await this.authorize(organizationId, request, 'workflows.read');
    const execution = await this.runtime.getExecution(organizationId, executionId);
    if (execution.workflowId !== workflowId)
      throw new ValidationError('Workflow execution not found');
    return { items: await this.runtime.listSteps(organizationId, executionId) };
  }

  @Post(':workflowId/executions/:executionId/approve')
  @ApiOperation({ summary: 'Approve and resume a workflow execution' })
  async approve(
    @Param('organizationId') organizationId: string,
    @Param('workflowId') workflowId: string,
    @Param('executionId') executionId: string,
    @Req() request: AuthenticatedRequest,
    @Body() value: unknown,
  ) {
    const authentication = await this.authorize(organizationId, request, 'workflows.run');
    const current = await this.runtime.getExecution(organizationId, executionId);
    if (current.workflowId !== workflowId)
      throw new ValidationError('Workflow execution not found');
    const parsed = approveSchema.safeParse(value);
    if (!parsed.success || parsed.data.approverId !== authentication.subject)
      throw new AuthorizationError('Approver must match authenticated principal');
    return this.runtime.approve({
      organizationId,
      executionId,
      approverId: parsed.data.approverId,
    });
  }

  @Post(':workflowId/executions/:executionId/recover')
  @ApiOperation({ summary: 'Recover a workflow execution after a process failure' })
  async recover(
    @Param('organizationId') organizationId: string,
    @Param('workflowId') workflowId: string,
    @Param('executionId') executionId: string,
    @Req() request: AuthenticatedRequest,
  ) {
    await this.authorize(organizationId, request, 'workflows.run');
    const current = await this.runtime.getExecution(organizationId, executionId);
    if (current.workflowId !== workflowId)
      throw new ValidationError('Workflow execution not found');
    return this.runtime.recover({ organizationId, executionId });
  }

  private async authorize(
    organizationId: string,
    request: AuthenticatedRequest,
    permission: string,
  ) {
    const authentication = requireAuthentication(request);
    if (authentication.organizationId !== organizationId)
      throw new AuthorizationError('Cross-organization workflow access is forbidden');
    const decision = await this.administration.authorize({
      organizationId,
      principalId: authentication.subject,
      permission,
    });
    if (!decision.allowed) throw new AuthorizationError(`${permission} permission is required`);
    return authentication;
  }
}

